//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::string::utf8_extract`; the
//! native twin is `benches/native/Bench/StringUtf8Extract.lean`.
//! the bytes copied into a new buffer, as Lean makes a new string

#![allow(
    unused_parens,
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]

use lean_runtime::semantics::string;
use lean_runtime_bench::{mixed, run, step, SEED};

#[allow(unused_variables)]
fn kernel(inp: &String, n: u64) -> u64 {
    let s = inp.as_bytes();
    let k = s.len() as u64;
    let m = k + 2;
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = acc.wrapping_add(
            s[string::utf8_extract(s, x % m, (x >> 32) % m)]
                .to_vec()
                .len() as u64,
        );
    }
    acc as u64
}

fn main() {
    run(|| mixed(), kernel)
}
